function status(s){if(!s)return '';const cls=/überfällig|Fehler|Verlust/.test(s)?'danger':/Achtung|Prüfen|Fällig|Unter Mindest|Unbekannt/.test(s)?'warning':/Aktiv|Unterschrieben|Reserviert|Abholbereit/.test(s)?'good':'';return `<span class="status ${cls}">${esc(s)}</span>`}
function row(r,extra=''){let target=r.to,interactive=!!target;return `<${interactive?'a':'div'} ${interactive?'href="'+href(target)+'"':''} class="row ${interactive?'interactive':''} ${extra}"><span class="row-copy"><span class="row-title">${esc(r.title)}</span>${r.sub?'<span class="row-sub">'+esc(r.sub)+'</span>':''}</span><span class="row-end">${r.value?'<span class="row-value">'+esc(r.value)+'</span>':''}${status(r.status)}</span>${interactive?'<span class="row-chevron" aria-hidden="true">›</span>':''}</${interactive?'a':'div'}>`}
function metrics(items){return items.length?'<div class="metrics">'+items.map(m=>`<div class="metric"><label>${esc(m.label)}</label><span class="value ${/überfällig/.test(m.label)?'danger-text':''}">${esc(m.value)}</span>${m.hint?'<small>'+esc(m.hint)+'</small>':''}</div>`).join('')+'</div>':''}
function tabs(items){if(!items.length)return '';return '<nav class="tabs" aria-label="Bereiche dieser Ansicht">'+items.map((t,i)=>typeof t==='string'?`<button class="tab ${i===0?'active':''}" data-tab="${esc(t)}" type="button" aria-pressed="${i===0}">${esc(t)}</button>`:`<a class="tab ${t.to===current.id&&items.findIndex(x=>typeof x==='object'&&x.to===current.id)===i?'active':''}" href="${href(t.to)}" ${t.to===current.id&&items.findIndex(x=>typeof x==='object'&&x.to===current.id)===i?'aria-current="page"':''}>${esc(t.label)}</a>`).join('')+'</nav>'}
function field(f){const id='field-'+(++fieldCount),req=f.required?'required':'';if(f.type==='checkbox')return `<label class="check" for="${id}"><input id="${id}" type="checkbox" ${f.value?'checked':''}>${esc(f.label)}</label>`;if(f.type==='signature')return `<div class="field"><label id="${id}-label">${esc(f.label)}</label><div class="signature-pad" role="img" aria-labelledby="${id}-label"><span>Hier unterschreiben</span></div></div>`;let control=f.type==='select'?`<select id="${id}" ${req}>${f.options.map(o=>`<option ${o===f.value?'selected':''}>${esc(o)}</option>`).join('')}</select>`:f.type==='textarea'?`<textarea id="${id}" ${req}>${esc(f.value)}</textarea>`:`<input id="${id}" type="${esc(f.type)}" ${f.type==='file'?'':`value="${esc(f.value)}"`} ${req} ${/Passwort/.test(f.label)?'autocomplete="off"':''}>`;return `<div class="field" data-field="${esc(f.label)}"><label for="${id}">${esc(f.label)}</label>${control}</div>`}
function fields(items){const normal=items.filter(f=>!f.rare),rare=items.filter(f=>f.rare);let html='',i=0;while(i<normal.length){if(i+1<normal.length&&['time','date'].includes(normal[i].type)&&normal[i+1].type===normal[i].type){html+='<div class="field-row">'+field(normal[i])+field(normal[i+1])+'</div>';i+=2}else html+=field(normal[i++])}if(rare.length)html+='<details class="further" '+(rare.some(f=>f.type!=='select'&&f.value!==''&&f.value!==false&&!/^0([,.]0+)?$/.test(String(f.value)))?'open':'')+'><summary>Weitere Angaben</summary><div class="further-body">'+rare.map(field).join('')+'</div></details>';return html}
