function positions(s){const isQuote=s.positionType==='quote';const entries=isQuote?[['Heizkörper liefern und montieren','2','Stk.','620,00','0'],['Arbeitszeit Facharbeiter','16','h','68,00','0']]:[['Facharbeiterstunden','23,50','h','68,00','0'],['Material aus den Scheinen','1','Pausch.','2000,00','0']];return '<section class="section"><div class="section-head"><h2>'+esc(s.title)+'</h2></div><div class="position-head" aria-hidden="true"><span>Bezeichnung</span><span>Menge</span><span>Einheit</span><span>EP netto €</span><span>Rabatt %</span></div>'+entries.map((e,i)=>'<div class="position-row">'+e.map((v,j)=>'<label><span class="position-mobile-label">'+['Bezeichnung','Menge','Einheit','EP netto €','Rabatt %'][j]+'</span><input aria-label="Position '+(i+1)+' '+['Bezeichnung','Menge','Einheit','Einzelpreis netto','Rabatt Prozent'][j]+'" value="'+esc(v)+'"></label>').join('')+'</div>').join('')+'<div class="foot-links">'+(isQuote?'<a class="btn text" href="#angebot-katalog">Aus dem Katalog</a>':'')+'<button class="btn text" data-demo="Position hinzufügen" type="button">Position hinzufügen</button><button class="btn text" data-demo="Text oder Überschrift hinzufügen" type="button">Text / Überschrift</button></div></section>'}
function section(s){if(s.kind==='positions')return positions(s);return `<section class="section"><div class="section-head"><h2>${esc(s.title)}</h2></div>${s.graphic==='budget'?budget():s.text?'<p class="section-text">'+esc(s.text)+'</p>':''}${s.fields?.length?'<div class="form">'+fields(s.fields)+'</div>':''}${s.rows?.map(r=>row(r)).join('')||''}</section>`}
function head(p,formMode=false){const secondary=p.secondary||[];return `<div class="page-head"><div><p class="eyebrow">${esc(p.domain)}${p.parent?' / <a href="'+href(p.parent)+'">Zurück</a>':''}</p><h1>${esc(p.title)}</h1>${p.subtitle?'<p class="subtitle">'+esc(p.subtitle)+'</p>':''}</div>${(!formMode&&p.primary)||secondary.length?'<div class="head-actions">'+(!formMode?action(p.primary,'btn primary'):'')+(secondary.length?'<details class="more"><summary aria-label="Weitere Aktionen">⋯</summary><div class="menu">'+secondary.map(a=>action(a,'menu-item')).join('')+'</div></details>':'')+'</div>':''}</div>`}
function formActions(p){return p.primary?`<div class="form-actions">${p.parent?'<a class="cancel" href="'+href(p.parent)+'">Abbrechen</a>':'<span></span>'}${p.primary.to?action(p.primary,'btn primary'): '<button type="submit" class="btn '+(p.kind==='confirm'?'danger':'primary')+'">'+esc(p.primary.label)+'</button>'}</div>`:''}
function renderForm(p){return `<form id="concept-form" class="${p.kind==='editor'?'editor':'form'}">${p.kind==='editor'?'<div class="form">'+fields(p.fields)+'</div>':fields(p.fields)}${p.sections.map(section).join('')}${p.rows.length?'<section class="section">'+p.rows.map(r=>row(r)).join('')+'</section>':''}${p.kind==='time-form'?'<div class="time-track" role="img" aria-label="8 Stunden Arbeit und 30 Minuten Pause"><span style="flex:480"></span><span style="flex:30"></span></div><div class="track-labels"><span>8:00 h Arbeit</span><span>0:30 h Pause</span></div><div class="duration"><span>Arbeitszeit ohne Pause</span><strong>8:00 h</strong></div>':''}${formActions(p)}</form>`}
function list(p){return `${p.fields.length?'<div class="form">'+fields(p.fields)+'</div>':''}<div class="toolbar"><label class="search"><input id="list-search" type="search" aria-label="${esc(p.title)} durchsuchen" placeholder="${p.domain==='Einstellungen'?'Einstellung suchen, z. B. Skonto oder IBAN':'Suchen'}"></label><span class="toolbar-meta">${p.rows.length} Einträge</span></div><div class="list-heading" aria-hidden="true"><span>${p.domain==='Kunden'?'Kunde / Kontakt':p.domain==='Lager'?'Artikel / Information':'Bezeichnung / Information'}</span><span>Stand</span></div><div id="rows">${p.rows.map(r=>row(r)).join('')}</div><div class="list-footer"><span>Alle Beispieltreffer geladen</span></div>${p.sections.map(section).join('')}`}
function dashboard(p){let task='<section class="section"><div class="section-head"><h2>Was jetzt ansteht</h2><span class="small muted">Nach Dringlichkeit</span></div>'+p.rows.map(r=>`<a class="dashboard-row" href="${href(r.to||'heute')}"><span class="priority ${r.status==='Achtung'?'warning':''}"></span><span class="row-copy"><span class="row-title">${esc(r.title)}</span><span class="row-sub">${esc(r.sub)}</span></span><span class="row-end">${esc(r.value)}</span><span class="row-chevron" aria-hidden="true">›</span></a>`).join('')+'</section>';return '<div class="two-col"><div>'+task+section({title:'Zuletzt geöffnet',rows:[{title:sonnenTitle(),sub:'Baustelle · B-2026-0147',to:role==='Mitarbeiter'?'meine-plaene':'baustelle'}]})+'</div><aside class="aside-col"><section class="section"><div class="section-head"><h2>Heute im Kalender</h2></div>'+[['07:00','Heizungstausch Sonnenhof','Max und Anton · Steigleitungen'],['10:30','Zwischenabnahme','Sonnenhof · Hausverwaltung'],['14:00','Besichtigung Familie Huber','Badumbau · Ringstraße 3']].map(t=>'<div class="day-item"><span class="day-time">'+t[0]+'</span><div><strong class="row-title">'+t[1]+'</strong><span class="row-sub">'+t[2]+'</span></div></div>').join('')+'</section>'+section({title:role==='Mitarbeiter'?'Dein Einsatz':'Team heute',rows:role==='Mitarbeiter'?[{title:'Heute mit Anton Berger',sub:'Steigleitungen · Stiege 2'}]:[{title:'Im Einsatz',value:'6 Personen'},{title:'Noch verfügbar',value:'2 Personen'}]})+'</aside></div>'}
function sonnenTitle(){return 'Heizungstausch Sonnenhof'}
function planner(p){const readonly=p.kind==='planner-read'||p.kind==='planner-absence';let tools='<div class="planner-tools"><button class="quiet" data-demo="Voriger Zeitraum" aria-label="Voriger Zeitraum">←</button><span class="period">'+esc(p.subtitle)+'</span><button class="quiet" data-demo="Nächster Zeitraum" aria-label="Nächster Zeitraum">→</button></div>';let agenda='<div class="week-mobile">'+[['Mi, 14. Oktober','Max und Anton','Heizungstausch Sonnenhof'],['Do, 15. Oktober','Max Mustermann','Sonnenhof · Heizkörpermontage'],['Fr, 16. Oktober','Anton Berger','Sonnenhof · Lieferung 08:00']].map(t=>'<section class="agenda-day"><h3>'+t[0]+'</h3>'+row({title:t[2],sub:t[1]+' · 07:00–15:30',to:readonly?null:'planung-einsatz'})+'</section>').join('')+'</div>';if(p.kind==='planner-day')return tools+section({title:'Einsätze am Mittwoch',rows:[{title:'Max Mustermann und Anton Berger',sub:'Sonnenhof · 07:00–15:30',to:'planung-einsatz'},{title:'Franz Hinterleitner',sub:'Neudorf · 08:00–12:00',to:'planung-einsatz'}]})+section({title:'Noch einzuplanen',rows:[{title:'2 Personen',sub:'Heute verfügbar'}]});if(p.kind==='planner-month'){let days=['Mo','Di','Mi','Do','Fr','Sa','So'].map(t=>'<div class="month-cell" style="min-height:42px;background:var(--soft)">'+t+'</div>').join('');for(let i=0;i<35;i++){const n=i-2,valid=n>0&&n<=31;days+='<div class="month-cell '+(n===14?'today':'')+'">'+(valid?n:'')+(valid&&n>=12&&n<=16?'<a class="month-event" href="#planung-tag">Sonnenhof<br>2 Personen</a>':'')+(n===19?'<span class="month-event">Abnahme · 10:00</span>':'')+'</div>'}return tools+'<div class="month">'+days+'</div>'+agenda}let grid='<div class="week"><div class="week-cell week-head">'+(p.kind==='planner-absence'?'Person':'Team')+'</div>'+['Mo 12.','Di 13.','Mi 14.','Do 15.','Fr 16.'].map(t=>'<div class="week-cell week-head">'+t+'</div>').join('');for(const [i,name] of ['Max Mustermann','Anton Berger','Sven Gruber','Daniel Hofer'].entries()){grid+='<div class="week-cell"><strong class="week-name">'+name+'</strong><small>'+('Monteur')+'</small></div>';for(let j=0;j<5;j++){if(i===3&&j>2)grid+='<div class="week-cell"><span class="cell-free">'+(readonly?'Abwesend':'Frei')+'</span></div>';else if(i===2&&j>2)grid+='<div class="week-cell"><span class="cell-free">'+(readonly?'Keine Einteilung':'Frei')+'</span></div>';else grid+='<div class="week-cell">'+(readonly?'<div':'<a href="#planung-einsatz"')+' class="assignment">'+(i===2?'Neudorf':'Sonnenhof')+'<small>07:00–15:30</small>'+ (readonly?'</div>':'</a>')+'</div>'}}grid+='</div>';return tools+grid+agenda+(readonly?'':'<div class="hint-line">Freitag · 2 Personen noch nicht eingeteilt. <a href="#planung-einsatz">Einsatz planen</a></div>')}
function accounting(p){return '<div class="toolbar"><label class="search"><input type="search" id="account-search" placeholder="Person suchen" aria-label="Person suchen"></label><span class="toolbar-meta">Oktober 2026</span></div><div id="account-rows">'+p.rows.map((r,i)=>'<a class="account-row" href="#mitarbeiter-person"><div><div class="account-name">'+esc(r.title)+'</div><div class="account-sub">'+esc(r.sub)+'</div></div><div class="month-strip" role="img" aria-label="Monatsstreifen: gebuchte Tage, fehlende Tage und arbeitsfreie Tage">'+Array.from({length:31},(_,n)=>'<span class="'+(n<13&&n%7<5?(n===8&&i===1?'missing':'booked'):'')+'"></span>').join('')+'</div><div class="account-number">'+(i===2?'60:00':'80:00')+' h<small>gebucht</small></div><div class="account-number">'+esc(r.value)+'<small>Gesamtsaldo</small></div></a>').join('')+'</div><p class="account-legend">Petrol: gebucht · rote Unterkante: Buchung fehlt · neutral: arbeitsfrei oder noch ohne Buchung.</p>'}
function invoiceSplit(p){return '<div class="invoice-work"><div>'+list({...p,fields:[],sections:[]})+'</div><aside class="invoice-side"><p class="kicker">Rechnungsdetails</p><h2>Hausverwaltung Sonnenhof</h2><p class="small muted">RE-2026-0234 · Heizungstausch</p><p style="margin-top:18px">'+status('14 Tage überfällig')+'</p><p class="small muted" style="margin-top:22px">Offener Betrag</p><p class="amount">€ 4.860,00</p><dl class="facts"><div class="fact"><dt>Zahlungsziel</dt><dd>30.09.2026</dd></div><div class="fact"><dt>Zahlungseingang</dt><dd>Noch keiner erfasst</dd></div><div class="fact"><dt>Baustelle</dt><dd><a href="#baustelle">B-2026-0147</a></dd></div></dl><a class="btn primary" href="#zahlung">Zahlung erfassen</a><a class="btn text" href="#mahnen">Mahnung prüfen →</a><a class="btn text" href="#rechnung-detail">Alle Rechnungsdetails →</a></aside></div>'}
function content(p){if(['schein-zeiten','schein-material','schein-fotos','schein-unterschrift'].includes(p.id)&&innerWidth>=1200){const stages=['schein-zeiten','schein-material','schein-fotos','schein-unterschrift'].map(id=>byId[id]);return renderForm({...p,kind:'form',fields:stages[0].fields,sections:[{title:'Material',rows:stages[1].rows,fields:stages[1].fields},{title:'Fotos und Ergänzungen',fields:stages[2].fields},{title:'Zusammenfassung',rows:stages[3].sections[0].rows},{title:'Unterschriften',fields:stages[3].fields}],primary:{label:'Unterschriebenen Schein abschließen'}})}if(['form','editor','time-form','signature'].includes(p.kind))return renderForm(p);if(p.kind==='dashboard')return dashboard(p);if(p.kind.startsWith('planner-'))return planner(p);if(p.kind==='accounting')return accounting(p);if(p.kind==='invoice-split')return invoiceSplit(p);if(p.kind==='loading')return '<div role="status" aria-label="Wird geladen"><div class="loading-line"></div>'+Array.from({length:6},()=>'<div class="loading-row"><span></span><span></span></div>').join('')+'</div>';if(p.kind==='document')return '<div class="document"><p class="kicker">Schematischer Platzhalter – kein ausführbarer Plan</p><h2>Heizraum · Installationsplan</h2><p class="section-text">In der App steht an dieser Stelle das tatsächliche Dokument.</p><div class="plan-drawing" role="img" aria-label="Neutrale schematische Dokumentfläche"><div class="plan-room">Heizraum · schematische Darstellung</div></div></div>';if(['panel','confirm'].includes(p.kind))return '<form id="concept-form" class="form">'+fields(p.fields)+p.sections.map(section).join('')+p.rows.map(r=>row(r)).join('')+formActions(p)+'</form>';if(p.kind==='state')return '<div class="state-body">'+p.sections.map(section).join('')+'</div>';if(p.kind==='search')return '<div class="form">'+fields(p.fields)+'</div>'+p.rows.map(r=>row(r)).join('');if(p.kind==='record'){const secs=p.sections;if(secs.length>=3)return '<div class="two-col record-body"><div>'+secs.slice(0,2).map(section).join('')+'</div><aside class="aside-col">'+secs.slice(2).map(section).join('')+'</aside></div>';return '<div class="record-body">'+secs.map(section).join('')+(p.rows.length?p.rows.map(r=>row(r)).join(''):'')+'</div>'}return list(p)}
function navigation(p){let nav=ROLE_MATRIX[role]?.nav||[],activePath=nav.map(n=>n.path).sort((a,b)=>b.length-a.length).find(path=>path!=='/'&&p.route.startsWith(path))||'/';if(role==='Plattformadministrator')nav=[{path:'/plattform',label:'Plattform',group:'Plattform'},{path:'/plattform/fehler',label:'Fehler',group:'Plattform'},{path:'/plattform/notzugang',label:'Notzugang',group:'Plattform'}];let groups=['Start','Aufträge','Material','Geld','Team','Einstellungen','Plattform'];let html='';for(let group of groups){let items=nav.filter(n=>n.group===group);if(!items.length)continue;if(group!=='Start'&&group!=='Einstellungen')html+='<div class="nav-group-label">'+group+'</div>';for(let n of items){let id=pathIds[n.path]||({'/plattform':'plattform','/plattform/fehler':'plattform-fehler','/plattform/notzugang':'plattform-notzugang'})[n.path]||'heute';if(n.path==='/time')id=role==='Mitarbeiter'?'zeit':['Verwaltung','Buchhaltung'].includes(role)?'zeit-buero':'zeit-leitung';if(n.path==='/settings'&&!ROLE_MATRIX[role]?.sub.some(s=>s.pfad==='uebersicht'))id='konto';if(n.path==='/')id=({'Mitarbeiter':'heute-monteur','Verwaltung':'heute-verwaltung','Buchhaltung':'heute-buchhaltung','Projektleiter':'heute-projektleitung','Administrator':'heute-admin'})[role]||'heute';html+='<a class="nav-link '+(activePath===n.path?'active':'')+'" href="'+href(id)+'">'+icon(navIcon(n.path))+esc(n.path==='/'?'Heute':n.label)+'</a>'}}return '<aside class="sidebar" aria-label="Hauptnavigation">'+mark()+'<div class="company">'+(role==='Plattformadministrator'?'Senklot Plattform':'Mustertechnik')+'<span>'+(role==='Plattformadministrator'?'Ohne Betriebszugriff':'Installationen GmbH')+'</span></div><button class="side-search" data-open-search>Suchen <span>⌘ K</span></button><nav class="side-nav">'+html+'</nav><div class="side-bottom"><strong>'+(role==='Mitarbeiter'?'Max Mustermann':role==='Verwaltung'?'Lisa Leitner':'Andrea Muster')+'</strong><span>'+esc(role)+'</span><small>Lot v2 · Entwurf 09</small></div></aside>'}
function mobileNav(){let paths=ROLE_MATRIX[role]?.mobile||['/'];return '<nav class="mobile-nav" aria-label="Hauptnavigation mobil">'+paths.slice(0,4).map(path=>{let id=pathIds[path];if(path==='/')id=({'Mitarbeiter':'heute-monteur','Verwaltung':'heute-verwaltung','Buchhaltung':'heute-buchhaltung','Projektleiter':'heute-projektleitung','Administrator':'heute-admin'})[role]||'heute';if(path==='/time')id=role==='Mitarbeiter'?'zeit':['Verwaltung','Buchhaltung'].includes(role)?'zeit-buero':'zeit-leitung';if(path==='/settings')id='konto';return '<a href="'+href(id)+'" class="'+(current.route.startsWith(path)&&path!=='/'?'active':'')+'">'+icon(navIcon(path))+'<span>'+esc({'/':'Heute','/time':'Zeit','/assignments':'Planung','/my-schedule':'Plan','/material':'Material','/customers':'Kunden','/anforderungen':'Anford.','/accounting':'Übersicht','/admin-projects':'Baustellen','/invoices':'Rechnungen'}[path]||'Öffnen')+'</span></a>'}).join('')+'<button data-open-more>'+icon('settings')+'<span>Mehr</span></button></nav>'}
function panelContext(p){const parent=byId[p.parent];if(!parent)return '<div class="context-preview" aria-hidden="true" inert></div>';const r=parent.rows.length?parent.rows:parent.sections.flatMap(s=>s.rows||[]);return '<div class="context-preview" aria-hidden="true" inert><h2>'+esc(parent.title)+'</h2><p class="small muted" style="margin:10px 0 25px">'+esc(parent.subtitle||'Deine vorherige Ansicht')+'</p>'+r.slice(0,6).map(x=>row({...x,to:null})).join('')+'</div>'}
function render(){const id=location.hash.slice(1)||'heute';current=byId[id]||byId.heute;role=current.role;fieldCount=0;searchText='';tabValue='';let p=current;if(invoiceContext&&p.id==='rechnung-detail'){p=JSON.parse(JSON.stringify(p));const nr=invoiceContext.sub.split(' · ')[0];p.title='Rechnung '+nr;p.subtitle=invoiceContext.title+' · '+invoiceContext.status;p.metrics=[{label:'Offener Betrag',value:invoiceContext.value}];p.sections[0].rows[0].sub=invoiceContext.sub.split('fällig ')[1]||'';p.sections[0].rows[2].title='Kunde';p.sections[0].rows[2].sub=invoiceContext.title;p.sections[0].rows[2].to=null;}if(invoiceContext&&p.id==='zahlung'){p=JSON.parse(JSON.stringify(p));p.fields.find(f=>f.label==='Betrag (€)').value=invoiceContext.value.replace('€','').replaceAll('.','').trim();p.subtitle=invoiceContext.title+' · '+invoiceContext.sub.split(' · ')[0];}document.title='Senklot · '+p.title+' – Revision 09';const formMode=['form','editor','time-form','signature','panel','confirm'].includes(p.kind);if(p.kind==='auth'){ $('#app').innerHTML='<div class="auth-layout"><aside class="auth-brand">'+mark()+'<p>Die Arbeit im Betrieb.<br>Klar organisiert, direkt erreichbar.</p></aside><main class="auth-main" id="main"><div class="auth-form"><h1>'+esc(p.title)+'</h1><p class="subtitle">'+esc(p.subtitle)+'</p>'+renderForm(p)+'<div class="auth-links">'+p.secondary.map(a=>action(a,'auth-link')).join('')+'</div><div class="auth-links">'+p.links.map(a=>action(a,'auth-link')).join('')+'</div><p class="auth-footer">Gestaltungsentwurf mit fiktiven Daten.</p></div></main></div>'}else if(p.kind==='legal'){$('#app').innerHTML='<main id="main" class="legal">'+mark()+'<h1>'+esc(p.title)+'</h1>'+p.sections.map(section).join('')+'<a class="btn text" href="#anmelden">Zur Anmeldung</a></main>'}else $('#app').innerHTML=navigation(p)+'<div class="workspace"><header class="topbar"><div class="context"><span>'+esc(role==='Plattformadministrator'?'Senklot':'Mustertechnik')+'</span><span class="divider">/</span><span>'+esc(p.domain)+'</span></div><div class="top-actions"><span class="top-label">Lot v2 · Entwurf 09</span><button class="quiet" data-open-help>Hilfe</button><button class="quiet" data-go="meldungen">Meldungen</button></div></header><header class="mobile-header">'+mark()+'<div><button class="quiet" data-open-search>Suchen</button></div></header><main id="main" class="content" tabindex="-1">'+(p.kind==='panel'?'<div class="panel-frame">'+panelContext(p):'')+'<div class="'+(p.kind==='panel'?'panel-screen':p.kind==='confirm'?'confirm-screen':'')+'">'+head(p,formMode)+metrics(p.metrics)+tabs(p.tabs)+content(p)+(p.links.length?'<div class="foot-links">'+p.links.map(a=>action(a,'foot-link')).join('')+'</div>':'')+'<p class="prototype-note">Gestaltungsentwurf · fiktive Beispieldaten</p></div>'+(p.kind==='panel'?'</div>':'')+'</main></div>'+mobileNav();window.scrollTo(0,0);document.body.dataset.page=p.id;document.body.dataset.ready='true';if(p.kind==='invoice-split')$('#rows .row')?.classList.add('selected');}
function showToast(t){clearTimeout(toastTimer);$('#toast').textContent=t;$('#toast').hidden=false;toastTimer=setTimeout(()=>$('#toast').hidden=true,5000)}
function dialog(title,html){$('#dialog-title').textContent=title;$('#dialog-body').innerHTML=html;if(!$('#dialog').open)$('#dialog').showModal()}
function globalSearch(){dialog('Suchen','<label class="field"><span class="small">Ansichten durchsuchen</span><input id="global-search" type="search" aria-label="Ansichten durchsuchen" placeholder="Kunde, Baustelle oder Einstellung"></label><div id="search-results"></div>');fillSearch('');$('#global-search').focus()}
function fillSearch(q){let arr=pages.filter(p=>p.roles.includes(role)&&!['Bestätigungen','Plattform','Werkzeug','Querschnitt','Zugang'].includes(p.domain)&&(p.title+' '+p.domain).toLowerCase().includes(q.toLowerCase()));$('#search-results').innerHTML=arr.slice(0,10).map(p=>'<a data-close-dialog href="#'+p.id+'">'+esc(p.title)+'<span class="small muted"> · '+esc(p.domain)+'</span></a>').join('')||'<p>Keine passenden Ansichten.</p>'}
function filterRows(){let rows=current.rows.filter(r=>(r.title+' '+r.sub+' '+r.value+' '+r.status).toLowerCase().includes(searchText.toLowerCase()));if(tabValue&&tabValue!==current.tabs[0]&&tabValue!=='Alle'){const re=({'Erledigt':'Erledigt|Bezahlt|Angenommen','Deaktiviert':'Deaktiviert','Verrechnet':'Verrechnet','Verworfen':'Verworfen','Entwürfe':'Entwurf','Geplant':'Geplant'})[tabValue];if(re)rows=rows.filter(r=>new RegExp(re,'i').test(r.status))}if($('#rows'))$('#rows').innerHTML=rows.length?rows.map(r=>row(r)).join(''):'<p class="section-text" style="padding:35px 0">Keine passenden Einträge in dieser Beispielansicht.</p>'}
document.addEventListener('click',e=>{if(e.target.closest('.skip')){e.preventDefault();$('#main')?.focus();return}const invoiceRow=e.target.closest('#rows .row');if(invoiceRow&&current.kind==='invoice-split'){const title=invoiceRow.querySelector('.row-title')?.textContent,sub=invoiceRow.querySelector('.row-sub')?.textContent;invoiceContext=current.rows.find(r=>r.title===title&&r.sub===sub)||null;if(invoiceContext&&innerWidth>=1200){e.preventDefault();document.querySelectorAll('#rows .row').forEach(r=>r.classList.toggle('selected',r===invoiceRow));$('.invoice-side h2').textContent=invoiceContext.title;$('.invoice-side .small.muted').textContent=invoiceContext.sub.split(' · ')[0];$('.invoice-side .amount').textContent=invoiceContext.value;$('.invoice-side p .status').outerHTML=status(invoiceContext.status);$('.invoice-side .fact dd').textContent=invoiceContext.sub.split('fällig ')[1]||'';return}}const to=e.target.closest('[data-go]');if(to){location.hash=to.dataset.go;return}const close=e.target.closest('[data-close-dialog]');if(close)$('#dialog').close();const demo=e.target.closest('[data-demo]');if(demo){showToast('Vorschau: '+demo.dataset.demo+' · keine echte Änderung.');return}const t=e.target.closest('[data-tab]');if(t){tabValue=t.dataset.tab;document.querySelectorAll('[data-tab]').forEach(b=>{b.classList.toggle('active',b===t);b.setAttribute('aria-pressed',String(b===t))});filterRows()}if(e.target.closest('[data-open-search]'))globalSearch();if(e.target.closest('[data-open-help]'))dialog('Hilfe zu dieser Seite','<p>'+esc(current.decision)+'</p><p style="margin-top:15px">Diese eigenständige Vorschau zeigt die Gestaltung und verwendet fiktive Daten.</p>');if(e.target.closest('[data-open-more]'))dialog('Weitere Bereiche',(ROLE_MATRIX[role]?.nav||[]).map(n=>'<a data-close-dialog href="#'+(pathIds[n.path]||'konto')+'">'+esc(n.label)+'</a>').join(''));if(e.target.closest('[data-close-button]'))$('#dialog').close()});
document.addEventListener('input',e=>{if(e.target.id==='list-search'){searchText=e.target.value;filterRows()}if(e.target.id==='global-search')fillSearch(e.target.value);if(e.target.id==='account-search'){const q=e.target.value.toLowerCase();document.querySelectorAll('.account-row').forEach(r=>r.hidden=!r.textContent.toLowerCase().includes(q))}if(current.kind==='time-form'&&e.target.closest('[data-field]')){const all=[...document.querySelectorAll('[data-field]')];const val=l=>all.find(f=>f.dataset.field===l)?.querySelector('input')?.value;const min=v=>v?.split(':').reduce((a,n,i)=>a+Number(n)*(i===0?60:1),0);const start=min(val('Von')),end=min(val('Bis')),pause=Number(val('Pause (Min.)')),mins=end-start-pause;const valid=Number.isFinite(mins)&&end>start&&pause>=0&&mins>0;const str=valid?Math.floor(mins/60)+':'+String(mins%60).padStart(2,'0')+' h':'—';$('.duration strong').textContent=str;$('.time-track').hidden=!valid;$('.track-labels').hidden=!valid;if(valid){$('.time-track span').style.flex=mins;$('.time-track span:last-child').style.flex=pause;$('.track-labels span').textContent=str+' Arbeit';$('.track-labels span:last-child').textContent=pause+' Min. Pause';$('.time-track').setAttribute('aria-label',str+' Arbeit und '+pause+' Minuten Pause')}}});
document.addEventListener('submit',e=>{e.preventDefault();if(current.kind==='time-form'&&$('.duration strong').textContent==='—'){showToast('Bitte Beginn, Ende und Pause prüfen.');return}showToast('Im Entwurf vorgemerkt · keine Betriebsdaten geändert.')});document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();globalSearch()}});window.addEventListener('hashchange',()=>{if($('#dialog').open)$('#dialog').close();render()});render();
let previousWide=innerWidth>=1200;window.addEventListener('resize',()=>{const next=innerWidth>=1200;if(next!==previousWide){previousWide=next;if(['schein-zeiten','schein-material','schein-fotos','schein-unterschrift'].includes(current.id))render()}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('#dialog').open){e.preventDefault();$('#dialog').close()}});
